function clean(value, lang) {
  let text = String(value || '').trim();
  const fence = String.fromCharCode(96).repeat(3);
  if (text.startsWith(fence)) text = text.slice(3).replace(new RegExp('^' + (lang || 'json'), 'i'), '').trim();
  if (text.endsWith(fence)) text = text.slice(0, -3).trim();
  return text;
}

let parsed;
try {
  parsed = JSON.parse(clean($json.output || $json.text || '', 'json'));
} catch (error) {
  return [{ json: { sql: '', expected_signal: '', sql_valid: false, guardrail_reason: 'SQL Writer trả JSON lỗi: ' + error.message } }];
}

let sql = clean(parsed.sql || '', 'sql').replace(/;\s*$/, '');
const reasons = [];
if (!/^(SELECT|WITH)\b/i.test(sql)) reasons.push('Query phải bắt đầu bằng SELECT hoặc WITH');
if (/\b(INSERT|UPDATE|DELETE|DROP|CREATE|MERGE|ALTER|TRUNCATE|CALL|EXECUTE|GRANT|REVOKE)\b/i.test(sql)) reasons.push('Có từ khóa ghi/xóa bị cấm');
if (sql.includes(';')) reasons.push('Không cho phép nhiều statement');
if (/SELECT\s+\*/i.test(sql)) reasons.push('Không cho phép SELECT *');
const limitMatch = sql.match(/\bLIMIT\s+(\d+)\b/i);
if (!limitMatch) reasons.push('Thiếu LIMIT');
else if (Number(limitMatch[1]) > 100) reasons.push('LIMIT vượt 100');

const tick = String.fromCharCode(96);
const refs = sql.split(tick).filter((_, index) => index % 2 === 1);
if (refs.some(ref => !ref.startsWith('tmdatabase.dm_base_crm.') && ref !== 'tmdatabase.dm_daily_brief.dim_course')) {
  reasons.push('Tham chiếu bảng ngoài allowlist');
}

return [{ json: {
  sql,
  expected_signal: String(parsed.expected_signal || '').slice(0, 500),
  sql_valid: reasons.length === 0,
  guardrail_reason: reasons.join('; ')
} }];

const rawRows = $input.all().map(item => item.json);
const errorRow = rawRows.find(row =>
  row?.error || row?.error_message || row?.errorMessage || Number(row?.statusCode || 0) >= 400
);
const rows = rawRows.filter(row => row && Object.keys(row).length > 0 && row !== errorRow).slice(0, 100);

return [{ json: {
  status: errorRow ? 'query_error' : 'ok',
  query_success: !errorRow,
  row_count: rows.length,
  rows,
  error_message: errorRow ? String(errorRow.error?.message || errorRow.error || errorRow.error_message || errorRow.errorMessage || 'BigQuery query error') : ''
} }];

