    finding: 'Chưa đủ dữ liệu để xác định nguyên nhân.',
    evidence: [],
    confidence: 'low',
    next_check: 'Evaluator trả JSON lỗi: ' + error.message
  };
}

const allowedStatus = ['supported', 'not_supported', 'insufficient_data'];
const allowedConfidence = ['high', 'medium', 'low'];
return [{ json: {
  status: allowedStatus.includes(parsed.status) ? parsed.status : 'insufficient_data',
  hypothesis: $('Parse RCA Hypothesis').first().json.hypothesis,
  finding: String(parsed.finding || 'Chưa đủ dữ liệu để xác định nguyên nhân.').slice(0, 800),
  evidence: Array.isArray(parsed.evidence) ? parsed.evidence.slice(0, 3).map(value => String(value).slice(0, 300)) : [],
  confidence: allowedConfidence.includes(parsed.confidence) ? parsed.confidence : 'low',
  next_check: String(parsed.next_check || '').slice(0, 500),
  expected_signal: $('SQL Guardrail').first().json.expected_signal,
  sql: $('SQL Guardrail').first().json.sql,
  row_count: $('Aggregate RCA Result').first().json.row_count
} }];

return [{ json: {
  status: 'insufficient_data',
  hypothesis: $json.hypothesis || 'Chưa tạo được giả thuyết RCA hợp lệ',
  finding: 'Chưa đủ dữ liệu để xác định nguyên nhân.',
  evidence: [],
  confidence: 'low',
  next_check: $json.priority_reason || $json.evidence_needed || 'Kiểm tra thủ công warning ưu tiên cao nhất',
  expected_signal: '', sql: '', row_count: 0
} }];

return [{ json: {
  status: 'query_blocked',
  hypothesis: $('Parse RCA Hypothesis').first().json.hypothesis,
  finding: 'Chưa đủ dữ liệu để xác định nguyên nhân vì query không vượt qua guardrail.',
  evidence: [],
  confidence: 'low',
  next_check: $json.guardrail_reason || $('Parse RCA Hypothesis').first().json.evidence_needed,
  expected_signal: $json.expected_signal || '', sql: $json.sql || '', row_count: 0
} }];

const input = $json || {};
const status = input.status || 'insufficient_data';
const hypothesis = input.hypothesis || 'Chưa tạo được giả thuyết RCA hợp lệ';
const finding = input.finding || 'Chưa đủ dữ liệu để xác định nguyên nhân.';
const evidence = Array.isArray(input.evidence) ? input.evidence.slice(0, 3) : [];
const confidence = input.confidence || 'low';
const nextCheck = input.next_check || '';
const confidenceLabel = { high: 'Cao', medium: 'Trung bình', low: 'Thấp' }[confidence] || 'Thấp';

const lines = [
  'Giả thuyết: ' + hypothesis,
  'Kết luận: ' + finding
];
if (evidence.length) {
  lines.push('Bằng chứng:');
  for (const item of evidence) lines.push('- ' + item);
}
lines.push('Độ tin cậy: ' + confidenceLabel);
if (nextCheck) lines.push('Cần kiểm tra tiếp: ' + nextCheck);

return [{ json: {
  status, hypothesis, finding, evidence, confidence,
  next_check: nextCheck,
  expected_signal: input.expected_signal || '',
  sql: input.sql || '',
  row_count: Number(input.row_count || 0),
  root_cause_text: lines.join('\n')
} }];
